rule.definition:
a!localVariables(

  /* Recurra a la integración y almacene la respuesta en una variable local */
  local!integrationResponse: #"_a-0000eea5-4822-8000-9cd8-011c48011c48_4956554"(),

  if(
    /* Esto devolverá True si la integración tiene éxito */
    local!integrationResponse.success,

    /* Si así lo requiere, modifique la siguiente expresión para devolver una lista de mapas, diccionarios, o CDT que se asignen a sus datos de registro */
    local!integrationResponse.result.body,

    /* Si la integración no es correcta, adminístrela como corresponde */

    if(
      /* Nota: la administración de excepciones fuera del límite varía según el servicio web */
      tointeger(index(local!integrationResponse.result, "statusCode", 0)) = 416,

      /* Si este es un error fuera del límite, devuelva una lista vacía para finalizar la sincronización */
      {},

      /* Si este es un error diferente, devuelve el error de integración. */
      /* Si necesita lógica adicional para determinar el error, utilice a!integrationError() en la integración para formatear el error mostrado en el monitor de sincronización */
      local!integrationResponse.error
    )
  )
)
